let saved=new Set(JSON.parse(localStorage.getItem('sataq-favs')||'[]')),active='Hamısı',visible=8;const grid=document.querySelector('#listingGrid'),search=document.querySelector('#searchInput'),empty=document.querySelector('#emptyState');document.querySelector('#categoryStrip').innerHTML=categories.map(c=>`<button class="category" data-category="${c[1]}"><span class="circle" style="--cat:${c[2]}">${c[0]}</span><b>${c[1]}</b></button>`).join('');const money=n=>new Intl.NumberFormat('az-AZ').format(n)+' ₼';function toast(t){let x=document.querySelector('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2000)}function render(){let q=search.value.trim().toLowerCase(),city=document.querySelector('#cityFilter').value,sort=document.querySelector('#sortSelect').value,data=listings.filter(x=>(active==='Hamısı'||x.category===active)&&(!q||(x.title+' '+x.detail).toLowerCase().includes(q))&&(!city||x.city===city));data.sort((a,b)=>sort==='low'?a.price-b.price:sort==='high'?b.price-a.price:b.id-a.id);document.querySelector('#resultText').textContent=data.length+ ' uyğun elan tapıldı';grid.innerHTML=data.slice(0,visible).map(x=>`<article class="listing-card"><a class="photo"><img src="${x.image}" alt="${x.title}" loading="lazy"></a><button class="fav ${saved.has(x.id)?'saved':''}" data-id="${x.id}">${saved.has(x.id)?'♥':'♡'}</button>${x.badge?`<span class="badge">${x.badge}</span>`:''}<h3>${x.title}</h3><div class="price">${money(x.price)}</div><div class="details">${x.detail}</div><div class="meta">${x.city} · ${x.time}</div></article>`).join('');empty.hidden=!!data.length;document.querySelector('#loadMore').style.display=data.length>visible?'block':'none';document.querySelector('#favCount').textContent=saved.size;document.querySelector('#clearSearch').style.display=q?'block':'none'}
document.addEventListener('click',e=>{let f=e.target.closest('.fav');if(f){let id=+f.dataset.id;saved.has(id)?saved.delete(id):saved.add(id);localStorage.setItem('sataq-favs',JSON.stringify([...saved]));render();toast(saved.has(id)?'Seçilmişlərə əlavə edildi':'Seçilmişlərdən silindi');return}let c=e.target.closest('[data-category]');if(c){active=c.dataset.category;visible=8;document.querySelectorAll('#chips button').forEach(b=>b.classList.toggle('active',b.dataset.category===active));render();document.querySelector('#listings').scrollIntoView({behavior:'smooth'});return}let q=e.target.closest('[data-query]');if(q){search.value=q.dataset.query;render()}});search.oninput=render;['cityFilter','sortSelect'].forEach(id=>document.querySelector('#'+id).onchange=render);document.querySelector('#clearSearch').onclick=()=>{search.value='';render()};document.querySelector('#searchBtn').onclick=render;document.querySelector('#loadMore').onclick=()=>{visible+=4;render()};document.querySelector('#catalogBtn').onclick=()=>document.querySelector('#categoryStrip').scrollIntoView({behavior:'smooth'});document.querySelector('#favsTop').onclick=()=>toast(saved.size?`${saved.size} seçilmiş elan`:'Seçilmiş elan yoxdur');document.querySelector('#openPost').onclick=()=>document.querySelector('#postDialog').showModal();document.querySelector('#postForm').onsubmit=e=>{e.preventDefault();let d=new FormData(e.target);listings.unshift({id:Date.now(),title:d.get('title'),price:+d.get('price'),city:d.get('city'),category:d.get('category'),image:'https://images.unsplash.com/photo-1560472354-b33ff0c44a43?auto=format&fit=crop&w=700&q=80',detail:'Yeni elan',time:'indi',badge:'Yeni'});e.target.reset();document.querySelector('#postDialog').close();active='Hamısı';render();toast('Elanınız yerləşdirildi')};render();
